input.command:
while true; do
  resp=$(curl -sS -H "Authorization: Bearer $GH_TOKEN" -H "Accept: application/vnd.github+json" \
    "https://api.github.com/repos/missingbulb/CrosswordChat/commits/8efcd64/check-runs" 2>/dev/null)
  statuses=$(echo "$resp" | node -e '
    let d="";process.stdin.on("data",c=>d+=c);process.stdin.on("end",()=>{
      try{
        const j=JSON.parse(d);
        const runs=j.check_runs||[];
        console.log(runs.map(r=>`${r.name}:${r.status}:${r.conclusion}`).join(" | "));
        const allDone = runs.length>0 && runs.every(r=>r.status==="completed");
        if(allDone) process.exit(42);
      }catch(e){console.log("parse-error:"+e.message)}
    });
  ')
  echo "$statuses"
  rc=$?
  if [ "$rc" = "42" ]; then
    echo "ALL_CONCLUDED"
    break
  fi
  sleep 20
done

